// FUNCTION: BFME2 0x00495489 size=721 name=?scanClosestTarget@CommandButtonHuntUpdate@@IAEPAVObject@@XZ evidence=N:ledger
Object *CommandButtonHuntUpdate::scanClosestTarget()
{
	const CommandButtonHuntUpdateModuleData *data = (const CommandButtonHuntUpdateModuleData *)getModuleData();
	Object *me = getObject();

	const SpecialPowerTemplate *spTemplate = m_commandButton->getSpecialPowerTemplate();
	if (!spTemplate)
		return NULL;

	Bool isCaptureBuilding = spTemplate->getSpecialPowerType() == 0x1D;
	Bool isPlaceExplosive = false;
	if (spTemplate->getSpecialPowerType() == 0x17)
		isPlaceExplosive = true;
	if (spTemplate->getSpecialPowerType() == 0x19)
		isPlaceExplosive = true;

	PartitionFilterAlive aliveFilter;
	PartitionFilterRelationship filterTeam(me, 1, false);
	PartitionFilterSameMapStatus filterNotMe(me);
	aliveFilter.link(&filterNotMe);
	if (!isCaptureBuilding)
		aliveFilter.link(&filterTeam);

	ObjectIterator iter = ThePartitionManager->iterateObjectsInRange(me->getPosition(), data->m_scanRange, 0, &aliveFilter, 1);

	Object *bestTarget = NULL;
	Real effectivePriority = 0;
	Real actualPriority = 0;
	const AttackPriorityInfo *info = NULL;
	if (me->getAI())
		info = me->getAI()->m_attackInfo;

	SpecialPowerModuleInterface *mod = me->getSpecialPowerModule(spTemplate);
	if (mod)
	{
		Object *other;
		while ((other = iter.next()) != NULL)
		{
			if (isCaptureBuilding)
			{
				if (me->getControllingPlayer() == other->getControllingPlayer())
					continue;
				if (me->getRelationship(other) == ALLIES)
					continue;
			}
			if (TheActionManager->canDoSpecialPowerAtObject(me, other, CMD_FROM_AI, spTemplate, 0, true))
			{
				if (isPlaceExplosive)
				{
					Real range = spTemplate->getViewObjectRange();
					Object *mine;
					{
						Rva00260E2AFilter filterPlayer(me->getControllingPlayer());
						mine = ThePartitionManager->getClosestObject(other->getPosition(), range, 1,
							PartitionFilterAcceptByKindOf(KindOfMaskType(KindOfMaskType::kInit, KINDOF_MINE), KINDOFMASK_NONE).link(&filterPlayer));
					}
					if (mine)
						continue;
				}
				Real distSqr = me->rva00263763(other);
				Real dist = (Real)sqrt(distSqr);
				Real curPriority = info ? info->getPriority(me, other, true) : data->m_scanRange - dist;
				if (curPriority == 0.0f)
					continue;
				Real modifier = dist / TheAI->getAiData()->m_attackPriorityDistanceModifier;
				Real modPriority = curPriority - modifier;
				if (modPriority < 1.0f)
					modPriority = 1.0f;
				if (modPriority > effectivePriority)
				{
					effectivePriority = modPriority;
					actualPriority = curPriority;
					bestTarget = other;
				}
				if (modPriority == effectivePriority && curPriority > actualPriority)
				{
					effectivePriority = modPriority;
					actualPriority = curPriority;
					bestTarget = other;
				}
			}
		}
	}

	return bestTarget;
}


